from collections import deque

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_valid(paren_string):
        stack = []
        for char in paren_string:
            if char == '(':
                stack.append((char, 1))
            elif char == ')':
                if not stack:
                    return False
                last = stack.pop()
                if last[1] - 1 == 0:
                    return False
                last = stack[-1]
                last[1] = last[1] - 1
        return not stack

    groups = deque()
    current_group = ''
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            if current_group:
                groups.append(current_group)
                current_group = f'({paren_string[i]}'
            else:
                current_group = '('
        elif paren_string[i] == ')':
            if current_group[0] == '(':
                if is_valid(current_group[1:]):
                    groups.append(current_group[:-1])
                    current_group = ''
                else:
                    current_group = current_group[:-1]
            else:
                current_group += paren_string[i]
    if current_group:
        groups.append(current_group)
    return list(groups)
```

