from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def _parse(s, nesting_level=0):
        if not s:
            return []
        stack = []
        for char in s:
            if char == '(':
                stack.append(nesting_level)
                nesting_level += 1
            elif char == ')':
                if nesting_level > 0:
                    nesting_level -= 1
                stack.pop()
        return [nesting_level for _ in stack if stack] + _parse(''.join(s[i:] for i, c in enumerate(s) if c != ')')

    return parse_nested_parens(paren_string)
