def factorize(n: int) -> List[int]:
    if n < 2:
        return []

    factors = set()
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.add(i)

    if n > 2:
        factors.add(n)

    return list(factors)
